#include "cpu_access.hpp"
#include "control_dot.hpp"
#include <chrono>
#include <iomanip>
#include <iostream>
#include <memory>
#include <numeric>
#if defined(_MSC_VER)
#define NOINLINE __declspec(noinline)
#else
#define NOINLINE __attribute__((noinline))
#endif
using Clock = std::chrono::steady_clock;
extern "C" NOINLINE float original_entry(const uint8_t* data,const float* x,size_t blocks,bool avx,bool f16) {
    return original_q8::dot(data,x,blocks,avx,f16);
}
extern "C" NOINLINE float split_entry(const uint8_t* scales,const uint8_t* weights,const float* x,size_t blocks,bool avx,bool f16) {
    return split_q8::dot(scales,weights,x,blocks,avx,f16);
}
struct Matrix {
    size_t rows,blocks;
    std::vector<uint8_t> original;
    std::unique_ptr<split_q8::PackedRows> packed;
    std::vector<float> out;
    double pack_ms;
    Matrix(size_t n,size_t k,uint32_t seed):rows(n),blocks(k/32),original(n*blocks*34),out(n) {
        for(size_t b=0;b<n*blocks;++b) {
            uint16_t h=uint16_t(0x2400+(b%0x400));
            original[b*34]=uint8_t(h);original[b*34+1]=uint8_t(h>>8);
            for(size_t j=0;j<32;++j) {seed=seed*1664525u+1013904223u;original[b*34+2+j]=uint8_t(seed>>24);}
        }
        auto start=Clock::now();packed=std::make_unique<split_q8::PackedRows>(original.data(),rows,blocks);
        pack_ms=std::chrono::duration<double,std::milli>(Clock::now()-start).count();
        if(packed->unpack()!=original) throw std::runtime_error("matrix pack roundtrip");
    }
};
template<bool Split> void run(backend::CpuBackend& cpu,const std::vector<std::unique_ptr<Matrix>>& matrices,const float* x) {
    const size_t nt=size_t(cpu.threads_available());
    cpu.run_parallel([&](int w) {
        for(const auto& owner:matrices) {
            auto& m=*owner;const size_t chunk=(m.rows+nt-1)/nt;
            const size_t first=size_t(w)*chunk,last=std::min(m.rows,first+chunk);
            for(size_t row=first;row<last;++row) {
                if constexpr(Split) m.out[row]=split_entry(m.packed->scale_row(row),m.packed->weight_row(row),x,m.blocks,cpu.avx2_,cpu.f16c_);
                else m.out[row]=original_entry(m.original.data()+row*m.blocks*34,x,m.blocks,cpu.avx2_,cpu.f16c_);
            }
        }
    });
}
int main() {
    try {
        backend::CpuBackend cpu;cpu.set_threads(6);
        if(!cpu.avx2_||!cpu.f16c_) throw std::runtime_error("AVX2/FMA/F16C required for diagnostic");
        struct Shape {const char* name;size_t nin,rows,count;int iterations;};
        const Shape shapes[]={{"small_up",1024,3072,1,256},{"small_gate_up",1024,3072,2,256},{"small_down",3072,1024,1,256},{"large_up",4096,12288,1,64},{"large_gate_up",4096,12288,2,64},{"large_down",12288,4096,1,64}};
        std::cout<<std::setprecision(12);
        for(const auto& shape:shapes) {
            std::vector<float> x(shape.nin);for(size_t j=0;j<x.size();++j)x[j]=float(int(j%257)-128)/129.0f;
            std::vector<std::unique_ptr<Matrix>> matrices;
            for(size_t i=0;i<shape.count;++i)matrices.emplace_back(std::make_unique<Matrix>(shape.rows,shape.nin,uint32_t(12345+i)));
            run<false>(cpu,matrices,x.data());
            std::vector<std::vector<float>> expected;for(const auto& m:matrices)expected.push_back(m->out);
            run<true>(cpu,matrices,x.data());
            for(size_t i=0;i<matrices.size();++i)if(std::memcmp(expected[i].data(),matrices[i]->out.data(),shape.rows*sizeof(float)))throw std::runtime_error("shape exact check");
            size_t original_bytes=0,packed_bytes=0;double pack_ms=0;
            for(const auto& m:matrices){original_bytes+=m->original.size();packed_bytes+=m->packed->scales.size()+m->packed->payload.size();pack_ms+=m->pack_ms;}
            std::cout<<"{\"kind\":\"shape\",\"name\":\""<<shape.name<<"\",\"nin\":"<<shape.nin<<",\"rows\":"<<shape.rows<<",\"matrices\":"<<shape.count<<",\"iterations\":"<<shape.iterations<<",\"original_bytes\":"<<original_bytes<<",\"packed_bytes\":"<<packed_bytes<<",\"pack_ms\":"<<pack_ms<<"}\n"<<std::flush;
            for(int pair=-1;pair<7;++pair)for(int order=0;order<2;++order) {
                bool split=(pair>=0 && pair%2)?order==0:order==1;
                auto start=Clock::now();
                for(int it=0;it<shape.iterations;++it){if(split)run<true>(cpu,matrices,x.data());else run<false>(cpu,matrices,x.data());}
                double ms=std::chrono::duration<double,std::milli>(Clock::now()-start).count();
                for(size_t i=0;i<matrices.size();++i)if(std::memcmp(expected[i].data(),matrices[i]->out.data(),shape.rows*sizeof(float)))throw std::runtime_error("timed shape exact check");
                std::cout<<"{\"kind\":\"sample\",\"name\":\""<<shape.name<<"\",\"pair\":"<<pair<<",\"arm\":\""<<(split?"split":"original")<<"\",\"ms\":"<<ms<<"}\n"<<std::flush;
            }
        }
    }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
}

