#define main arithmetic_main
#include "oracle.cpp"
#undef main

static uint64_t packed_bytes = 0, packed_rows = 0, packing_cases = 0;
static void packing_case(size_t rows, size_t blocks, size_t offset, bool every_half) {
    const size_t count = rows * blocks;
    std::vector<uint8_t> source(offset + count * 34 + 1, 173);
    uint8_t* data = source.data() + offset;
    for (size_t b = 0; b < count; ++b) {
        const uint16_t h = uint16_t(every_half ? b : b * 4051 + 32769);
        data[b * 34] = uint8_t(h); data[b * 34 + 1] = uint8_t(h >> 8);
        for (size_t j = 0; j < 32; ++j) data[b * 34 + j + 2] = uint8_t(b + j * 17);
    }
    const auto original = source;
    split_q8::PackedRows packed(data, rows, blocks);
    require(packed.rows == rows && packed.blocks == blocks, "packed dimensions changed");
    require(packed.scales.size() == count * 2 + 16 && packed.payload.size() == count * 32 + 31, "packed extents changed");
    require(packed.payload_offset < 32, "invalid payload offset");
    const auto unpacked = packed.unpack();
    require(unpacked.size() == count * 34 && std::equal(unpacked.begin(), unpacked.end(), data), "packed roundtrip differs");
    for (size_t row = 0; row < rows; ++row) {
        require((reinterpret_cast<uintptr_t>(packed.weight_row(row)) & 31) == 0, "row payload unaligned");
        for (size_t b = 0; b < blocks; ++b) {
            const uint8_t* want = data + (row * blocks + b) * 34;
            require(std::memcmp(packed.scale_row(row) + b * 2, want, 2) == 0, "scale bytes differ");
            require(std::memcmp(packed.weight_row(row) + b * 32, want + 2, 32) == 0, "payload bytes differ");
        }
    }
    require(source == original, "packing modified source");
    packed_bytes += count * 34; packed_rows += rows; ++packing_cases;
}

static void packing_checks() {
    for (size_t rows : {size_t(0), size_t(1), size_t(2), size_t(7), size_t(65)})
        for (size_t blocks : {size_t(0), size_t(1), size_t(2), size_t(3), size_t(7), size_t(9), size_t(33)})
            for (size_t offset : {size_t(0), size_t(1), size_t(7), size_t(15)})
                packing_case(rows, blocks, offset, false);
    packing_case(65536, 1, 1, true);
    const size_t limit = std::numeric_limits<size_t>::max();
    for (auto dims : {std::pair<size_t,size_t>{limit, 2}, {limit / 34 + 1, 1}}) {
        bool rejected = false;
        try { split_q8::PackedRows invalid(nullptr, dims.first, dims.second); }
        catch (const std::runtime_error&) { rejected = true; }
        require(rejected, "size overflow was not rejected before source access");
    }
}

static void route_witness() {
    backend::CpuBackend cpu; cpu.set_threads(6);
    Matrix a(65, 3), b(67, 3);
    alignas(32) float input[97]{};
    float* x = input + 1;
    for (size_t i = 0; i < 96; ++i) x[i] = float(int(i * 47 % 127) - 63) / 13.0f;
    const std::vector<float> original(x, x + 96);
    const auto a_bytes = a.bytes, b_bytes = b.bytes;
    split_witness::mode.store(1);
    cpu.matmul_group({a.project(a.group), b.project(b.group)}, x, 96, 1);
    require(split_witness::calls[1].load() == 132, "group did not use split dot for every row");
    split_witness::mode.store(2);
    for (Matrix* m : {&a, &b}) {
        cpu.matvec_q8_0(m->data(), x, m->separate.data() + 1, 3, m->rows);
        split_q8::PackedRows persistent(m->data(), m->rows, 3);
        for (size_t row = 0; row < m->rows; ++row) {
            const float expected = scalar(m->data() + row * 3 * 34, x, 3, true);
            compare(expected, m->group[row + 1], expected, "split group witness", row);
            compare(expected, m->separate[row + 1], expected, "split standalone witness", row);
            for (bool hardware_half : {true, false})
                compare(expected, split_q8::dot(persistent.scale_row(row), persistent.weight_row(row), x, 3, true, hardware_half), expected, "persistent split row", row);
        }
    }
    require(split_witness::calls[2].load() == 132, "standalone did not use split dot for every row");
    split_witness::mode.store(0);
    require(std::equal(original.begin(), original.end(), x) && a.bytes == a_bytes && b.bytes == b_bytes, "split dot modified input");
}

int main() {
    if (arithmetic_main()) return 1;
    try {
        require(split_witness::calls[0].load() > 0, "original oracle did not activate split dot");
        packing_checks(); route_witness();
        std::cout << "{\"packing_cases\":" << packing_cases << ",\"packing_rows\":" << packed_rows
                  << ",\"packing_bytes\":" << packed_bytes << ",\"ordinary_split_calls\":" << split_witness::calls[0].load()
                  << ",\"group_split_calls\":" << split_witness::calls[1].load()
                  << ",\"standalone_split_calls\":" << split_witness::calls[2].load() << "}\n";
        return 0;
    } catch (const std::exception& error) { std::cerr << error.what() << '\n'; return 1; }
}

