#include "candidate_access.hpp"
#include "control_access.hpp"
#include <array>
#include <cfenv>
#include <iomanip>
#include <iostream>
#include <stdexcept>

static uint64_t finite_checks = 0, nonfinite_checks = 0, direct_checks = 0;
static uint64_t scale_checks = 0, grouped_checks = 0, standalone_checks = 0;
static uint32_t random_state = 12345;
static uint32_t next() { random_state = random_state * 1664525u + 1013904223u; return random_state; }
static void require(bool value, const char* text) { if (!value) throw std::runtime_error(text); }
static uint32_t bits(float value) { uint32_t out; std::memcpy(&out, &value, 4); return out; }
static float from_bits(uint32_t value) { float out; std::memcpy(&out, &value, 4); return out; }
static float add(float a, float b) { volatile float value = a + b; return value; }
static float mul(float a, float b) { volatile float value = a * b; return value; }

static float half(uint16_t value) {
    const unsigned exponent = (value >> 10) & 31, fraction = value & 1023;
    float result;
    if (exponent == 31) result = fraction ? std::numeric_limits<float>::quiet_NaN() : std::numeric_limits<float>::infinity();
    else if (exponent == 0) result = std::ldexp(float(fraction), -24);
    else result = std::ldexp(float(1024 + fraction), int(exponent) - 25);
    return std::copysign(result, (value & 32768) ? -1.0f : 1.0f);
}

static float scalar(const uint8_t* row, const float* x, size_t blocks, bool simd_order) {
    float lanes[4][8]{};
    float sequential = 0;
    for (size_t b = 0; b < blocks; ++b) {
        const uint8_t* w = row + b * 34;
        const float scale = half(uint16_t(w[0] | uint16_t(w[1]) << 8));
        for (size_t j = 0; j < 32; ++j) {
            const int weight = w[j + 2] < 128 ? int(w[j + 2]) : int(w[j + 2]) - 256;
            const float product = mul(float(weight), scale);
            if (simd_order) lanes[j / 8][j % 8] = std::fma(product, x[b * 32 + j], lanes[j / 8][j % 8]);
            else sequential = add(sequential, mul(product, x[b * 32 + j]));
        }
    }
    if (!simd_order) return sequential;
    float merged[8];
    for (size_t j = 0; j < 8; ++j) merged[j] = add(add(lanes[0][j], lanes[1][j]), add(lanes[2][j], lanes[3][j]));
    const float a = add(merged[0], merged[4]), b = add(merged[1], merged[5]);
    const float c = add(merged[2], merged[6]), d = add(merged[3], merged[7]);
    return add(add(a, b), add(c, d));
}

static void compare(float control, float candidate, float expected, const char* label, size_t detail) {
    if (std::isfinite(control) && std::isfinite(candidate) && std::isfinite(expected)) {
        if (bits(control) != bits(candidate) || bits(candidate) != bits(expected)) {
            std::cerr << std::setprecision(17) << label << " detail=" << detail
                << " control=" << control << " candidate=" << candidate << " expected=" << expected
                << " bits=" << bits(control) << ',' << bits(candidate) << ',' << bits(expected) << '\n';
            throw std::runtime_error("finite bit comparison failed");
        }
        ++finite_checks;
    } else {
        const auto classification = [](float v) {
            return std::isnan(v) ? 0 : std::isinf(v) ? (std::signbit(v) ? -1 : 1) : 2;
        };
        if (classification(control) != classification(candidate) || classification(candidate) != classification(expected)) {
            std::cerr << label << " detail=" << detail << '\n';
            throw std::runtime_error("nonfinite classification differs");
        }
        ++nonfinite_checks;
    }
}

static void fill_weights(uint8_t* data, size_t rows, size_t blocks, bool extremes) {
    static const uint16_t scales[] = {0, 0x8000, 1, 0x8001, 0x03ff, 0x0400, 0x2000,
        0x3800, 0x3c00, 0xbc00, 0x7bff, 0xfbff};
    for (size_t r = 0; r < rows; ++r) for (size_t b = 0; b < blocks; ++b) {
        uint8_t* w = data + (r * blocks + b) * 34;
        const uint16_t scale = extremes ? scales[(r * 3 + b) % 12] : uint16_t((r + b) % 2 ? 0x3800 : 0xbc00);
        w[0] = uint8_t(scale); w[1] = uint8_t(scale >> 8);
        for (size_t j = 0; j < 32; ++j) w[j + 2] = uint8_t(next() >> 24);
    }
}

static void direct(backend::CpuBackend& candidate, control_backend::CpuBackend& control, bool simd_order) {
    for (size_t blocks : {size_t(0), size_t(1), size_t(2), size_t(3), size_t(7), size_t(8), size_t(9), size_t(31), size_t(32), size_t(33), size_t(127)}) {
        for (size_t offset = 0; offset < 8; ++offset) for (size_t byte_offset : {size_t(0), size_t(1), size_t(7), size_t(15)}) {
            std::vector<float> storage(blocks * 32 + 8);
            std::vector<uint8_t> weights(blocks * 34 + 16);
            float* x = storage.data() + offset;
            uint8_t* row = weights.data() + byte_offset;
            fill_weights(row, 1, blocks, true);
            for (int kind = 0; kind < 6; ++kind) {
                for (size_t i = 0; i < blocks * 32; ++i) {
                    if (kind == 0) x[i] = (i & 1) ? -0.0f : 0.0f;
                    else if (kind == 1) x[i] = float(int(next() % 257) - 128) / 17.0f;
                    else if (kind == 2) {
                        const int exponents[] = {-149, -126, -100, -40, -1, 0, 60, 100, 127};
                        x[i] = std::copysign(std::ldexp(1.0f, exponents[i % 9]), (i & 1) ? -1.0f : 1.0f);
                    } else if (kind == 3) x[i] = std::copysign(std::numeric_limits<float>::max(), (i & 1) ? -1.0f : 1.0f);
                    else if (kind == 4) x[i] = from_bits((next() % 0x7f800000u) | (next() & 0x80000000u));
                    else x[i] = (i & 1) ? -1.00000011920928955078125f : 1.0f;
                }
                compare(control.dot_q8_0(row, x, blocks), candidate.dot_q8_0(row, x, blocks), scalar(row, x, blocks, simd_order), "direct", blocks);
                ++direct_checks;
            }
        }
    }
}

static void all_scales(backend::CpuBackend& candidate, control_backend::CpuBackend& control) {
    std::array<uint8_t, 35> storage{};
    uint8_t* row = storage.data() + 1;
    alignas(32) float aligned[33]{};
    float* x = aligned + 1;
    for (unsigned value = 0; value < 65536; ++value) {
        if ((value & 0x7c00) == 0x7c00) continue;
        row[0] = uint8_t(value); row[1] = uint8_t(value >> 8);
        const size_t lane = value % 32;
        x[lane] = (value & 1) ? -1.0f : 1.0f;
        for (int weight : {-128, -1, 0, 127}) {
            std::fill(row + 2, row + 34, uint8_t(weight));
            compare(control.dot_q8_0(row, x, 1), candidate.dot_q8_0(row, x, 1), scalar(row, x, 1, true), "finite-half", value);
            ++scale_checks;
        }
        x[lane] = 0;
    }
}

struct Matrix {
    size_t rows, blocks;
    std::vector<uint8_t> bytes;
    std::vector<float> separate, group, old;
    Matrix(size_t r, size_t b) : rows(r), blocks(b), bytes(r * b * 34 + 1),
        separate(r + 2, 123456.0f), group(separate), old(separate) { fill_weights(bytes.data() + 1, r, b, false); }
    const uint8_t* data() const { return bytes.data() + 1; }
    backend::Projection project(std::vector<float>& output) { return {gguf::GGML_TYPE_Q8_0, data(), output.data() + 1, rows}; }
};

static void routes(backend::CpuBackend& candidate, control_backend::CpuBackend& control) {
    candidate.matmul_group({}, nullptr, 0, 1);
    for (int threads : {1, 2, 6}) {
        candidate.set_threads(threads); control.set_threads(threads);
        for (size_t blocks : {size_t(1), size_t(3), size_t(7), size_t(32)}) {
            for (size_t rows : {size_t(0), size_t(1), size_t(7), size_t(47), size_t(48), size_t(49), size_t(65)}) {
                for (size_t offset : {size_t(0), size_t(1), size_t(7)}) {
                    std::vector<float> storage(blocks * 32 + 8);
                    float* x = storage.data() + offset;
                    for (size_t i = 0; i < blocks * 32; ++i) x[i] = float(int(next() % 257) - 128) / 17.0f;
                    const auto original = storage;
