                    control.matmul_group({a.project(a.old), b.project(b.old), c.project(c.old)}, x, blocks * 32, 1);
                    candidate.matmul_group({a.project(a.group), b.project(b.group), c.project(c.group)}, x, blocks * 32, 1);
                    for (Matrix* m : {&a, &b, &c}) {
                        candidate.matvec_q8_0(m->data(), x, m->separate.data() + 1, blocks, m->rows);
                        require(m->group.front() == 123456 && m->group.back() == 123456 &&
                                m->separate.front() == 123456 && m->separate.back() == 123456 &&
                                m->old.front() == 123456 && m->old.back() == 123456, "route output boundary");
                        for (size_t r = 0; r < m->rows; ++r) {
                            const float expected = scalar(m->data() + r * blocks * 34, x, blocks, true);
                            compare(m->old[r + 1], m->group[r + 1], expected, "group", r);
                            compare(m->old[r + 1], m->separate[r + 1], expected, "standalone", r);
                            ++grouped_checks; ++standalone_checks;
                        }
                    }
                    require(storage == original, "route modified input");
                }
            }
        }
    }
}

static void nonfinite(backend::CpuBackend& candidate, control_backend::CpuBackend& control, bool simd_order) {
    std::vector<uint8_t> weights(3 * 34);
    std::vector<float> x(3 * 32, 1.0f);
    for (uint16_t scale : {uint16_t(0x7c00), uint16_t(0xfc00), uint16_t(0x7e00), uint16_t(0xfe00), uint16_t(0x7c01), uint16_t(0xfc01)}) {
        for (size_t b = 0; b < 3; ++b) {
            fill_weights(weights.data(), 1, 3, false);
            weights[b * 34] = uint8_t(scale); weights[b * 34 + 1] = uint8_t(scale >> 8);
            compare(control.dot_q8_0(weights.data(), x.data(), 3), candidate.dot_q8_0(weights.data(), x.data(), 3), scalar(weights.data(), x.data(), 3, simd_order), "nonfinite-scale", scale);
        }
    }
    for (uint32_t value : {0x7f800000u, 0xff800000u, 0x7fc00000u, 0xffc00000u, 0x7f800001u}) {
        fill_weights(weights.data(), 1, 3, false);
        for (size_t lane : {size_t(0), size_t(7), size_t(8), size_t(15), size_t(16), size_t(23), size_t(24), size_t(31)}) {
            x[lane] = from_bits(value);
            compare(control.dot_q8_0(weights.data(), x.data(), 3), candidate.dot_q8_0(weights.data(), x.data(), 3), scalar(weights.data(), x.data(), 3, simd_order), "nonfinite-input", lane);
            x[lane] = 1;
        }
    }
}

int main() {
    try {
        std::fesetround(FE_TONEAREST);
        _mm_setcsr(_mm_getcsr() & ~0x8040u);
        backend::CpuBackend candidate;
        control_backend::CpuBackend control;
        candidate.set_threads(1); control.set_threads(1);
        require(candidate.avx2_ && candidate.f16c_ && control.avx2_ && control.f16c_, "hardware AVX2/F16C required for this test");
        for (bool hardware_half : {true, false}) {
            candidate.f16c_ = hardware_half; control.f16c_ = hardware_half;
            direct(candidate, control, true);
            all_scales(candidate, control);
            routes(candidate, control);
            nonfinite(candidate, control, true);
            std::cout << "completed simd hardware_half=" << hardware_half << '\n' << std::flush;
        }
        candidate.set_threads(1); control.set_threads(1);
        candidate.avx2_ = false; control.avx2_ = false;
        direct(candidate, control, false);
        nonfinite(candidate, control, false);
        std::cout << "{\"finite_bit_checks\":" << finite_checks << ",\"nonfinite_class_checks\":" << nonfinite_checks
            << ",\"direct_checks\":" << direct_checks << ",\"finite_half_checks\":" << scale_checks
            << ",\"grouped_checks\":" << grouped_checks << ",\"standalone_checks\":" << standalone_checks << "}\n";
        return 0;
    } catch (const std::exception& error) { std::cerr << error.what() << '\n'; return 1; }
}

