split_q8.hpp.text:
#pragma once
#include <cstdint>
#include <cstring>
#include <limits>
#include <stdexcept>
#include <vector>
#include <immintrin.h>
#include "core/fp16.hpp"
#include "format/gguf.hpp"
namespace split_q8 {
struct PackedRows {
    size_t rows, blocks, payload_offset;
    std::vector<uint8_t> scales, payload;
    PackedRows(const uint8_t* source, size_t row_count, size_t block_count)
        : rows(row_count), blocks(block_count), payload_offset(0) {
        const size_t limit = std::numeric_limits<size_t>::max();
        if (blocks && rows > limit / blocks) throw std::runtime_error("packed size overflow");
        const size_t count = rows * blocks;
        if (count > (limit - 32) / 34) throw std::runtime_error("packed size overflow");
        scales.resize(count * 2 + 16);
        payload.resize(count * 32 + 31);
        payload_offset = (32 - (reinterpret_cast<uintptr_t>(payload.data()) & 31)) & 31;
        for (size_t b = 0; b < count; ++b) {
            std::memcpy(scales.data() + b * 2, source + b * 34, 2);
            std::memcpy(payload.data() + payload_offset + b * 32, source + b * 34 + 2, 32);
        }
    }
    PackedRows(const PackedRows&) = delete;
    PackedRows& operator=(const PackedRows&) = delete;
    const uint8_t* scale_row(size_t row) const { return scales.data() + row * blocks * 2; }
    const uint8_t* weight_row(size_t row) const { return payload.data() + payload_offset + row * blocks * 32; }
    std::vector<uint8_t> unpack() const {
        std::vector<uint8_t> result(rows * blocks * 34);
        for (size_t b = 0; b < rows * blocks; ++b) {
            std::memcpy(result.data() + b * 34, scales.data() + b * 2, 2);
            std::memcpy(result.data() + b * 34 + 2, payload.data() + payload_offset + b * 32, 32);
        }
        return result;
    }
};
inline float dot(const uint8_t* scales, const uint8_t* weights, const float* x, size_t nblocks, bool avx2_, bool f16c_) {
        if (avx2_) {
            // Four independent accumulators. A single chained accumulator
            // serialised the loop at FMA latency, which also capped how many
            // loads could be in flight; decode is bandwidth bound, so fewer
            // outstanding loads means less memory-level parallelism and less
            // achieved bandwidth.
            __m256 s0 = _mm256_setzero_ps(), s1 = _mm256_setzero_ps();
            __m256 s2 = _mm256_setzero_ps(), s3 = _mm256_setzero_ps();
            // Software prefetch of the weight stream was measured here and
            // made no difference (4.10/4.14 against 4.12/4.12 tok/s): the
            // hardware prefetcher already keeps up with these sequential
            // streams. Not reinstated.
            for (size_t b = 0; b < nblocks; b++) {
                const uint8_t* y = weights + b * 32;
                const uint8_t* scale = scales + b * 2;
                // Hardware f16 convert. The scalar f16_to_f32 is a branchy
                // function (zero, subnormal, inf/nan cases) called once per
                // 34 bytes of weights, which is a lot of unpredictable control
                // flow in a loop whose job is to keep loads in flight.
                __m256 dv;
                if (f16c_) {
                    dv = _mm256_cvtph_ps(_mm_broadcastw_epi16(_mm_loadu_si128((const __m128i*)scale)));
                } else {
                    const uint16_t h = (uint16_t)(scale[0] | ((uint16_t)scale[1] << 8));
                    dv = _mm256_set1_ps(f16_to_f32(h));
                }
                __m256 f0 = _mm256_cvtepi32_ps(_mm256_cvtepi8_epi32(_mm_loadl_epi64((const __m128i*)(y))));
                __m256 f1 = _mm256_cvtepi32_ps(_mm256_cvtepi8_epi32(_mm_loadl_epi64((const __m128i*)(y + 8))));
                __m256 f2 = _mm256_cvtepi32_ps(_mm256_cvtepi8_epi32(_mm_loadl_epi64((const __m128i*)(y + 16))));
                __m256 f3 = _mm256_cvtepi32_ps(_mm256_cvtepi8_epi32(_mm_loadl_epi64((const __m128i*)(y + 24))));
                const float* xp = x + b * gguf::Q8_0_BLOCK;
                s0 = _mm256_fmadd_ps(_mm256_mul_ps(f0, dv), _mm256_loadu_ps(xp), s0);
                s1 = _mm256_fmadd_ps(_mm256_mul_ps(f1, dv), _mm256_loadu_ps(xp + 8), s1);
                s2 = _mm256_fmadd_ps(_mm256_mul_ps(f2, dv), _mm256_loadu_ps(xp + 16), s2);
                s3 = _mm256_fmadd_ps(_mm256_mul_ps(f3, dv), _mm256_loadu_ps(xp + 24), s3);
            }
            __m256 acc = _mm256_add_ps(_mm256_add_ps(s0, s1), _mm256_add_ps(s2, s3));
            __m128 lo = _mm256_castps256_ps128(acc);
            __m128 hi = _mm256_extractf128_ps(acc, 1);
            __m128 s = _mm_add_ps(lo, hi);
            s = _mm_hadd_ps(s, s);
            s = _mm_hadd_ps(s, s);
            return _mm_cvtss_f32(s);
        }
        float acc = 0.0f;
        for (size_t b = 0; b < nblocks; b++) {
            const uint8_t* y = weights + b * 32;
                const uint8_t* scale = scales + b * 2;
            uint16_t d16 = (uint16_t)(scale[0] | ((uint16_t)scale[1] << 8));
            float d = f16_to_f32(d16);
            for (int j = 0; j < gguf::Q8_0_BLOCK; j++)
                acc += (float)(int8_t)y[j] * d * x[b * gguf::Q8_0_BLOCK + j];
        }
        return acc;
    }
}

